-- REVIEW ONLY. Verify within the same transaction before any commit.
DO $postflight$
BEGIN
 IF (SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('scorekeeper_publish_versions','scorekeeper_publish_receipts','scorekeeper_operators','scorekeeper_operator_sessions','scorekeeper_operator_assignments','scorekeeper_operator_rate_windows','scorekeeper_oidc_flows','scorekeeper_login_budget')) <> 8 THEN RAISE EXCEPTION 'Incomplete Scorekeeper schema'; END IF;
 IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='scorekeeper_publish_versions' AND column_name='event_id' AND data_type='uuid') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='ftg_games' AND column_name='away_fouls' AND is_nullable='YES') THEN RAISE EXCEPTION 'Unexpected migration result'; END IF;
 IF has_table_privilege('scorekeeper_auth_access','public.ftg_games','INSERT') OR NOT has_table_privilege('scorekeeper_publish_access','public.ftg_games','INSERT') OR has_table_privilege('scorekeeper_publish_access','public.scorekeeper_publish_receipts','DELETE') OR has_table_privilege('scorekeeper_publish_access','public.scorekeeper_publish_receipts','UPDATE') OR has_column_privilege('scorekeeper_publish_access','public.ftg_events','is_published','UPDATE') OR has_column_privilege('scorekeeper_auth_access','public.scorekeeper_operators','active','UPDATE') THEN RAISE EXCEPTION 'Unsafe runtime permissions'; END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('scorekeeper_auth_access','scorekeeper_publish_access') AND (rolcanlogin OR rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls)) THEN RAISE EXCEPTION 'Unsafe runtime group'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.scorekeeper_publish_receipts'::regclass AND tgname='scorekeeper_receipts_no_update_delete' AND tgenabled='O') THEN RAISE EXCEPTION 'Receipt protection missing'; END IF;
END $postflight$;
